17: function makeSetup(){const saved=localStorage.getItem('shinobi-save');$('#setup').innerHTML=`<div class="eyebrow">Seu destino começa agora</div><h1>Que tipo de shinobi<br>você vai se tornar?</h1><p class="setup-copy">Uma vida inteira no mundo ninja. Faça amigos, treine, aceite missões e escolha o que vale a pena proteger. Cada decisão deixa uma marca.</p><div class="form-grid"><div class="field"><label for="name">Nome</label><input id="name" maxlength="20" placeholder="Ex.: Ren" value="${saved?escapeHtml(JSON.parse(saved).name):''}"></div><div class="field"><label for="clan">Clã / origem</label><select id="clan">${clans.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field form-wide"><label for="village">Vila natal</label><select id="village">${villages.map(v=>`<option>${v}</option>`).join('')}</select></div></div><div class="start-row">${saved?'<button class="primary" id="resume">Continuar jornada&nbsp; →</button>':''}<button class="${saved?'secondary':'primary'}" id="start">${saved?'Nova vida':'Começar minha história'}&nbsp; →</button>${saved?'':'<span class="tiny">A partir dos 6 anos · salvamento automático</span>'}</div>${saved?'<div style="margin-top:16px;color:#64806b;font-size:12px">Sua jornada está salva neste dispositivo.</div>':''}`;
