Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -59,9 +59,9 @@
 function stat(label,key,color=''){let value=clamp(state[key]);return `<div class="stat"><div class="stat-label"><span>${label}</span><b>${value}</b></div><div class="bar ${color}"><i style="width:${value}%"></i></div></div>`}
 function render(){if(!state)return;$('#setup').classList.add('hidden');$('#game').classList.remove('hidden');const initials=state.name.slice(0,1).toUpperCase();const stage=state.age<12?'Academia Ninja':state.age<18?'Equipe Genin':state.age<30?'Shinobi de carreira':state.age<60?'Veterano':'Legado ninja';
 if(state.finished){$('#game').innerHTML=`<div class="panel ending"><div class="eyebrow">Fim de uma jornada extraordinária</div><h2>${state.name}, uma vida lembrada</h2><p>Aos ${state.age} anos, você deixa um legado de ${state.renown} pontos de reputação. As histórias de seus feitos continuarão inspirando a próxima geração.</p><button class="primary" onclick="newLife()">Começar outra vida&nbsp; →</button></div>`;return}
 $('#game').innerHTML=`<div class="game-header"><div><div class="eyebrow">${state.village} · ${state.clan}</div><h1 class="game-title">A vida de ${state.name}</h1><p class="subtitle">${stage} · ${state.phase}</p></div><div><div class="year-badge">Ano ${state.age-5} da jornada</div><div class="calendar-line"><span>CALENDÁRIO DO MUNDO NINJA</span><strong>Ano ${state.worldYear} · ${state.age} anos</strong><small>Data fictícia da linha do tempo de Naruto</small></div></div></div><div class="layout"><div class="left-column"><article class="panel story"><div class="story-top"><span class="story-tag">Capítulo ${state.age-5} · ${state.age} anos</span><span class="tiny">${state.phase}</span></div><h2>${state.event.title}</h2><p>${state.event.text}</p><div class="choices">${state.event.choices.map((c,i)=>`<button class="choice" onclick="choose(${i})"><span>${c.label}</span><span class="arrow">→</span></button>`).join('')}</div><footer>Uma escolha por ano · As consequências moldam sua história</footer></article>
-<div class="panel activities"><div class="section-head"><h3 class="section-title">O que você faz este ano?</h3><span class="counter">${state.activities}/2 atividades</span></div><div class="activity-grid">${actions.map((a,i)=>`<button class="activity" onclick="doAction(${i})" ${state.activities>=2||(state.energy<5&&i!==4)?'disabled':''}><span class="icon">${a.icon}</span><strong>${a.title}</strong><small>${a.title==='Fazer missão'&&state.age<12?'Desbloqueia aos 12 anos':a.hint}</small></button>`).join('')}</div>${state.combat?`<div class="combat-panel"><div class="combat-top"><span>Duelo: ${escapeHtml(state.combat.name)}</span><span>${state.combat.health} / ${state.combat.maxHealth} PV</span></div><div class="combat-vitals"><span>Oponente</span><div class="combat-bar"><i style="width:${Math.max(0,state.combat.health/state.combat.maxHealth*100)}%"></i></div></div><div class="combat-vitals player"><span>${escapeHtml(state.name)}</span><div class="combat-bar"><i style="width:${state.health}%"></i></div><b>${state.health} PV</b><span>◉ ${state.chakraPoints} chakra</span></div><div class="battle-actions"><button onclick="combatTurn('atacar')">Atacar</button><button onclick="combatTurn('jutsu')" ${state.chakraPoints<12?'disabled':''}>Usar jutsu · 12 chakra</button><button onclick="combatTurn('defender')">Defender / concentrar</button><button onclick="combatTurn('fugir')">Fugir</button></div></div>`:''}<div class="year-control"><span class="year-note">Sua escolha no capítulo acima encerra o ano e avança a história.</span><span class="counter">♡ energia ${state.energy}%</span></div></div>
+<div class="panel activities"><div class="section-head"><h3 class="section-title">O que você faz este ano?</h3><span class="counter">${state.activities}/2 atividades</span></div><div class="activity-grid">${actions.map((a,i)=>`<button class="activity" onclick="doAction(${i})" ${state.activities>=2||(state.energy<5&&i!==4)?'disabled':''}><span class="icon">${a.icon}</span><strong>${a.title}</strong><small>${a.title==='Fazer missão'&&state.age<12?'Desbloqueia aos 12 anos':a.title==='Fazer missão'&&state.rogue?'Aceite um trabalho clandestino':a.hint}</small></button>`).join('')}</div>${state.combat?`<div class="combat-panel"><div class="combat-top"><span>Duelo: ${escapeHtml(state.combat.name)}</span><span>${state.combat.health} / ${state.combat.maxHealth} PV</span></div><div class="combat-vitals"><span>Oponente</span><div class="combat-bar"><i style="width:${Math.max(0,state.combat.health/state.combat.maxHealth*100)}%"></i></div></div><div class="combat-vitals player"><span>${escapeHtml(state.name)}</span><div class="combat-bar"><i style="width:${state.health}%"></i></div><b>${state.health} PV</b><span>◉ ${state.chakraPoints} chakra</span></div><div class="battle-actions"><button onclick="combatTurn('atacar')">Atacar</button><button onclick="combatTurn('jutsu')" ${state.chakraPoints<12?'disabled':''}>Usar jutsu · 12 chakra</button><button onclick="combatTurn('defender')">Defender / concentrar</button><button onclick="combatTurn('fugir')">Fugir</button></div></div>`:''}<div class="year-control"><span class="year-note">Sua escolha no capítulo acima encerra o ano e avança a história.</span><span class="counter">♡ energia ${state.energy}%</span></div></div>
 <div class="panel journal-panel"><div class="section-head"><h3 class="section-title">Memórias recentes</h3><span class="counter">Diário</span></div><div class="journal-list">${state.journal.length?state.journal.slice(0,4).map(j=>`<div class="journal-item"><time>${j.age}a</time><span>${j.text}</span></div>`).join(''):'<div class="tiny">Suas escolhas importantes aparecerão aqui.</div>'}</div></div></div>
 <aside class="right-column"><div class="panel stats-panel"><div class="profile"><div class="avatar">${initials}</div><div><div class="profile-name">${state.name}</div><div class="profile-sub">${state.clan} · ${state.phase}</div></div></div><div class="stats-grid">${stat('Chakra','chakra','blue')}${stat('Taijutsu','taijutsu','red')}${stat('Ninjutsu','ninjutsu','blue')}${stat('Inteligência','intel')}${stat('Vínculos','bond','green')}${stat('Reputação','renown','green')}</div><div class="resources"><div class="resource">Energia<b>${state.energy} / 100</b></div><div class="resource">Ryō<b>¥ ${state.ryo}</b></div><div class="resource">Vitalidade<b>${state.health} / 100</b></div><div class="resource">Chakra de combate<b>${state.chakraPoints} / 100</b></div></div><button class="secondary rogue-button" onclick="becomeRogue()" ${state.rogue?'disabled':''}>${state.rogue?'✓ Ninja rogue · Nukenin':'Abandonar a vila e tornar-se ninja rogue'}</button></div>
 <div class="panel rel-panel"><div class="section-head"><h3 class="section-title">Seu círculo</h3><span class="counter">Laços</span></div><div class="rel-list">${state.relations.map(r=>`<div class="rel"><div class="rel-face">${r.face}</div><div class="rel-info"><div class="rel-name">${r.name}</div><div class="rel-role">${r.role}</div></div><div class="rel-meter"><i style="width:${r.value}%"></i></div></div>`).join('')}</div></div><div style="display:flex;justify-content:space-between;align-items:center;padding:0 2px"><span class="tiny">Progresso salvo automaticamente</span><button class="secondary" style="padding:7px 10px;font-size:11px" onclick="confirmRestart()">Nova vida</button></div></aside></div>`;state.year=state.age-6;}
 function skipActivities(){toast('Você segue para o próximo capítulo. Escolha um caminho!')}
